create table project_cost_change_log (
  change_id bigserial primary key,
  table_name text not null check (table_name in ('project_cost_items', 'project_cost_assumptions', 'project_cost_tasks')),
  row_id text not null,
  cost_model_id text not null,
  op text not null check (op in ('UPDATE', 'DELETE')),
  changed_columns text[] not null,
  old_values jsonb not null,
  new_values jsonb,
  reason text,
  changed_by text,
  changed_at timestamptz not null default now()
);
create index project_cost_change_log_row_idx on project_cost_change_log (table_name, row_id, changed_at desc);
create index project_cost_change_log_model_idx on project_cost_change_log (cost_model_id, changed_at desc);
comment on table project_cost_change_log is 'コスト試算の明細・前提・作業を書き換えた・消したときの前の値と後の値。トリガー project_cost_log_change が書く（画面の保存も migration も）。理由は set_config(''amd.cost_change_reason'', …, true) で渡す。migration 431（2026-09-14 まさ「こういうことが起きないようにして」）';

alter table project_cost_change_log enable row level security;
create policy project_cost_change_log_admin_read on project_cost_change_log
  for select to authenticated using (is_admin());
create policy project_cost_change_log_service_role on project_cost_change_log
  for all to service_role using (true) with check (true);

create or replace function project_cost_log_change() returns trigger
language plpgsql security definer set search_path = public as $fn$
declare
  watched text[];
  pk text;
  o jsonb := to_jsonb(OLD);
  n jsonb := case when TG_OP = 'UPDATE' then to_jsonb(NEW) else null end;
  changed text[] := '{}';
  col text;
  claims jsonb;
begin
  if TG_TABLE_NAME = 'project_cost_items' then
    pk := 'cost_item_id';
    watched := array['scenario','cost_type','group_label','mid_label','leaf_label','basis','quantity','quantity_unit','unit_price','unit_price_unit','price_rule','annual_factor','useful_life_years','is_breakdown','confidence','source_kind','owner','note','visibility','strain','application','bearer'];
  elsif TG_TABLE_NAME = 'project_cost_assumptions' then
    pk := 'cost_assumption_id';
    watched := array['group_label','label','value','value_text','unit','confidence','source_kind','owner','is_key','role_key','note','visibility','strain','application'];
  else
    pk := 'cost_task_id';
    watched := array['scenario','strain','application','group_label','label','hours_per_occurrence','count_driver','count_per_year','hourly_rate','expense_per_occurrence','performer','confidence','source_kind','owner','note','visibility'];
  end if;
  foreach col in array watched loop
    if TG_OP = 'DELETE' or (o -> col) is distinct from (n -> col) then
      changed := changed || col;
    end if;
  end loop;
  if cardinality(changed) = 0 then
    return null;
  end if;
  begin
    claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
  exception when others then
    claims := null;
  end;
  insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by)
  values (
    TG_TABLE_NAME, o ->> pk, o ->> 'cost_model_id', TG_OP, changed,
    (select jsonb_object_agg(c, o -> c) from unnest(changed) as c),
    case when n is null then null else (select jsonb_object_agg(c, n -> c) from unnest(changed) as c) end,
    nullif(current_setting('amd.cost_change_reason', true), ''),
    coalesce(claims ->> 'email', claims ->> 'role', session_user)
  );
  return null;
end
$fn$;
revoke all on function project_cost_log_change() from public;

create trigger project_cost_items_change_log after update or delete on project_cost_items
  for each row execute function project_cost_log_change();
create trigger project_cost_assumptions_change_log after update or delete on project_cost_assumptions
  for each row execute function project_cost_log_change();
create trigger project_cost_tasks_change_log after update or delete on project_cost_tasks
  for each row execute function project_cost_log_change();

