insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'ci_260820_120', 'cm_p21_260820', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'confidence', 'source_kind', 'owner', 'note']::text[], '{"leaf_label": "培地主原料", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 9, "unit_price_unit": "円/kg-DCW", "confidence": "C", "source_kind": "仮置き", "owner": "AMD", "note": "菌体の製造拠点で発生する菌体製造費。現場設備OPEXとは分離し「菌体の製造拠点」の区分へ。菌体製造原価として事業全体で別途配賦する。 二段階版で 円/m³ → 円/kg-DCW へ換算した（旧版の基準菌体量 1.111 kg-DCW/m³ で割った値）。"}'::jsonb, '{"leaf_label": "窒素源（硝酸ナトリウム）", "quantity": 0.4854, "quantity_unit": "kg/kg-DCW", "unit_price": 187, "unit_price_unit": "円/kg", "confidence": "B", "source_kind": "推定", "owner": "杉浦先生（培地の組成）", "note": "量: 菌体の乾燥重量の8%が窒素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis の測定では11.3%）→ 窒素0.08kg ÷ 硝酸ナトリウムの窒素の割合16.5% ＝ 0.4854kg。培地に入れた窒素はすべて菌体が吸う（培養液を使い回す前提。マテバラ推定と同じ。閉鎖型の培養で吸う割合を20%と置く試算もあり（米国PNNL 2018）、その場合は5倍）。買値: 硝酸ナトリウムの財務省貿易統計の輸入単価（chematels.com の集計、2026年） 187円/kg。届け先までの運賃は含まない。確かめ方: 杉浦先生の培地の窒素源と濃さ（培養液1Lに何g）を聞き、菌体1kgあたりの量と比べる。尿素（窒素46.6%、輸入単価の2026年平均 約107円/kg）が使えるなら菌体1kgあたり約18円に下がる。リン源のりん酸二アンモニウムからも窒素が約9g入るが、ここから差し引いていない。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
