insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'ci_260820_123', 'cm_p21_260820', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'source_kind', 'owner', 'note']::text[], '{"leaf_label": "CO2", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 4.5, "unit_price_unit": "円/kg-DCW", "source_kind": "仮置き", "owner": "AMD", "note": "二段階版で 円/m³ → 円/kg-DCW へ換算した（旧版の基準菌体量 1.111 kg-DCW/m³ で割った値）。"}'::jsonb, '{"leaf_label": "CO2（液化炭酸ガス）", "quantity": 2.29, "quantity_unit": "kg/kg-DCW", "unit_price": 50, "unit_price_unit": "円/kg", "source_kind": "推定", "owner": "杉浦先生（CO2の入れ方）", "note": "量: 菌体の乾燥重量の半分が炭素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis 51.4%）→ 菌体1kgに固定するCO2 1.83kg。供給したCO2のうち菌体に固定する割合を80%（同じ設計仮定）として2.29kg。固定する割合は培養のしかたで大きく変わり、閉鎖型の袋の培養で10%と置く試算（米国PNNL 2018）では8倍、開放池で75%（米国エネルギー省 2023）。買値: 50円/kg の仮置き。液化炭酸ガスの卸の相場 FOB東京 約225ドル/t（2026年4〜6月、ChemAnalyst）は1ドル150円で約34円/kgで、届け先までの運賃と貯槽の費用を足した。施設園芸のボンベ買いでは約120円/kg。メーカー各社は2023〜2025年に15〜30%ずつ値上げしている。確かめ方: CO2をどう入れるか（ボンベ・液化炭酸ガスの貯槽・工場の排ガス）と、吸わせきれる割合を杉浦先生に聞き、液化炭酸ガスはメーカー（日本液炭・エア・ウォーター炭酸など）に量と場所で見積を取る。工場の排ガスから回収するなら、国の2030年目標で回収だけ 2,000円台/t（1kgあたり約2〜3円）。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
