insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'ci_260820_127', 'cm_p21_260820', 'UPDATE', array['quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'owner', 'note']::text[], '{"quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 9, "unit_price_unit": "円/kg-DCW", "owner": "AMD", "note": "二段階版で 円/m³ → 円/kg-DCW へ換算した（旧版の基準菌体量 1.111 kg-DCW/m³ で割った値）。"}'::jsonb, '{"quantity": 0.2, "quantity_unit": "m³/kg-DCW", "unit_price": 45, "unit_price_unit": "円/m³", "owner": "中島先生（濃縮のしかた）", "note": "仮置き（膜やフィルタの買値を調べられていない）。2026-08-20版の試算シートでAMDが置いた額（処理水1m³あたり10円）を、培養液1m³あたり45円に直して、菌体1kgの培養液0.2m³（菌体の濃さ5g/L、杉浦先生の回答）を掛けている。確かめ方: 濃縮を遠心分離にするか膜にするかを中島先生と決め、膜なら膜の面積・交換の年数・1m²の値段を見積もって、1年の額 ÷ 1系列が1年に作る菌体の量で比べる（遠心分離ならフィルタはほぼ要らず、電力が要る）。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
