insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'ci_260820_134', 'cm_p21_260820', 'UPDATE', array['quantity', 'quantity_unit', 'unit_price', 'owner', 'note']::text[], '{"quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 5.4, "owner": "AMD", "note": "二段階版で 円/m³ → 円/kg-DCW へ換算した（旧版の基準菌体量 1.111 kg-DCW/m³ で割った値）。"}'::jsonb, '{"quantity": 0.05, "quantity_unit": "kg-DCW/kg-DCW", "unit_price": 261.6, "owner": "杉浦先生（培養の失敗の割合）", "note": "仮置き。培養がうまくいかずに作り直す割合を5%とし、上の原料9行の菌体1kgあたりの合計（261.6円）を掛ける。上の行を書き換えても、この行の単価は自動では変わらない。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_120', 'cm_p21_fuel_260914', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'confidence', 'source_kind', 'owner', 'note']::text[], '{"leaf_label": "培地主原料", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 9, "unit_price_unit": "円/kg-DCW", "confidence": "C", "source_kind": "仮置き", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 培地の組成（培養液1Lに入れる原料のg数）と原料の買値から培養液1m³あたりの額を出し、45円と比べる。菌体の濃さ5g/L（杉浦先生の回答）なら、菌体1kgに培養液200Lを使うので、菌体1kgあたり9円は培養液1m³あたり45円にあたる。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり10円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり9円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"leaf_label": "窒素源（硝酸ナトリウム）", "quantity": 0.4854, "quantity_unit": "kg/kg-DCW", "unit_price": 187, "unit_price_unit": "円/kg", "confidence": "B", "source_kind": "推定", "owner": "杉浦先生（培地の組成）", "note": "量: 菌体の乾燥重量の8%が窒素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis の測定では11.3%）→ 窒素0.08kg ÷ 硝酸ナトリウムの窒素の割合16.5% ＝ 0.4854kg。培地に入れた窒素はすべて菌体が吸う（培養液を使い回す前提。マテバラ推定と同じ。閉鎖型の培養で吸う割合を20%と置く試算もあり（米国PNNL 2018）、その場合は5倍）。買値: 硝酸ナトリウムの財務省貿易統計の輸入単価（chematels.com の集計、2026年） 187円/kg。届け先までの運賃は含まない。確かめ方: 杉浦先生の培地の窒素源と濃さ（培養液1Lに何g）を聞き、菌体1kgあたりの量と比べる。尿素（窒素46.6%、輸入単価の2026年平均 約107円/kg）が使えるなら菌体1kgあたり約18円に下がる。リン源のりん酸二アンモニウムからも窒素が約9g入るが、ここから差し引いていない。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_121', 'cm_p21_fuel_260914', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'confidence', 'source_kind', 'owner', 'note']::text[], '{"leaf_label": "栄養塩", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 10.8, "unit_price_unit": "円/kg-DCW", "confidence": "C", "source_kind": "仮置き", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 菌体は乾燥重量の約1割が窒素、約1%がリンなので、菌体1kgを作るには窒素を約0.1kg、リンを約0.01kg吸わせる（培地に残る分は別に要る）。使う塩（硝酸塩やリン酸塩など）の量と買値から菌体1kgあたりの額を出し、10.8円と比べる。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり12円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり10.8円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"leaf_label": "リン源（りん酸二アンモニウム）", "quantity": 0.0426, "quantity_unit": "kg/kg-DCW", "unit_price": 161, "unit_price_unit": "円/kg", "confidence": "B", "source_kind": "推定", "owner": "杉浦先生（培地の組成）", "note": "量: 菌体の乾燥重量の1%がリン（2026-09-07 の工程とマテバラ推定の設計仮定。微細藻類で0.3〜1.2%）→ リン0.01kg ÷ りん酸二アンモニウムのリンの割合23.5% ＝ 0.0426kg。入れたリンはすべて菌体が吸う（使い回す前提）。買値: りん酸二アンモニウムの財務省貿易統計の輸入単価（chematels.com の集計、2026年） 161円/kg。確かめ方: 杉浦先生の培地のリン源と濃さを聞いて比べる。BG-11（シアノバクテリアの標準の培地）のリン酸カリウムのままでは、菌体の濃さ5g/Lに足りない（約0.7g/L分）。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_122', 'cm_p21_fuel_260914', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'source_kind', 'owner', 'note']::text[], '{"leaf_label": "微量元素・添加剤", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 7.2, "unit_price_unit": "円/kg-DCW", "source_kind": "仮置き", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 培地に入れる鉄やマンガンなどの微量元素と添加剤のg数と買値から培養液1m³あたりの額を出し、36円と比べる。菌体の濃さ5g/L（杉浦先生の回答）なら、菌体1kgに培養液200Lを使うので、菌体1kgあたり7.2円は培養液1m³あたり36円にあたる。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり8円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり7.2円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"leaf_label": "カリウム・マグネシウム・鉄・微量金属", "quantity": 0.074, "quantity_unit": "kg/kg-DCW", "unit_price": 324, "unit_price_unit": "円/kg", "source_kind": "推定", "owner": "杉浦先生（培地の組成）", "note": "量: 菌体の乾燥重量のカリウム1.6%・マグネシウム0.3%・鉄0.1%（スピルリナの成分の総説）から、塩化カリウム0.0305kg・硫酸マグネシウム7水塩0.0304kg・キレート鉄13% 0.0077kg、微量金属の塩（ホウ酸・塩化マンガン・硫酸亜鉛など）をBG-11の鉄との割合で0.0054kg、合わせて0.074kg。買値は重さで割り戻した平均 324円/kg: 塩化カリウム 77円/kg（財務省貿易統計の輸入単価（chematels.com の集計、2026年））、硫酸マグネシウム 162円/kg（肥料・工業用25kg、通販 2026-09）、キレート鉄 1,468円/kg（25kg、通販 2026-09）、微量金属の塩 1,000円/kg（買値を調べていない仮置き）。菌体1kgあたりの額の半分近くがキレート鉄。確かめ方: 杉浦先生の培地の組成を聞き、成分ごとの量と比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_123', 'cm_p21_fuel_260914', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'source_kind', 'owner', 'note']::text[], '{"leaf_label": "CO2", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 4.5, "unit_price_unit": "円/kg-DCW", "source_kind": "仮置き", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 菌体は乾燥重量の約半分が炭素なので、菌体1kgを作るのにCO2を約1.8kg吸わせる（吸いきれずに抜ける分は別に要る）。この額はCO2 1kgあたり約2.5円にあたる。CO2をどこから入れるか（買う液化炭酸ガスか、工場の排ガスか）と、その値段と吸わせきれる割合から菌体1kgあたりの額を出して比べる。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり5円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり4.5円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"leaf_label": "CO2（液化炭酸ガス）", "quantity": 2.29, "quantity_unit": "kg/kg-DCW", "unit_price": 50, "unit_price_unit": "円/kg", "source_kind": "推定", "owner": "杉浦先生（CO2の入れ方）", "note": "量: 菌体の乾燥重量の半分が炭素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis 51.4%）→ 菌体1kgに固定するCO2 1.83kg。供給したCO2のうち菌体に固定する割合を80%（同じ設計仮定）として2.29kg。固定する割合は培養のしかたで大きく変わり、閉鎖型の袋の培養で10%と置く試算（米国PNNL 2018）では8倍、開放池で75%（米国エネルギー省 2023）。買値: 50円/kg の仮置き。液化炭酸ガスの卸の相場 FOB東京 約225ドル/t（2026年4〜6月、ChemAnalyst）は1ドル150円で約34円/kgで、届け先までの運賃と貯槽の費用を足した。施設園芸のボンベ買いでは約120円/kg。メーカー各社は2023〜2025年に15〜30%ずつ値上げしている。確かめ方: CO2をどう入れるか（ボンベ・液化炭酸ガスの貯槽・工場の排ガス）と、吸わせきれる割合を杉浦先生に聞き、液化炭酸ガスはメーカー（日本液炭・エア・ウォーター炭酸など）に量と場所で見積を取る。工場の排ガスから回収するなら、国の2030年目標で回収だけ 2,000円台/t（1kgあたり約2〜3円）。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_124', 'cm_p21_fuel_260914', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'confidence', 'source_kind', 'owner', 'note']::text[], '{"leaf_label": "補給水", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 1.8, "unit_price_unit": "円/kg-DCW", "confidence": "C", "source_kind": "仮置き", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 蒸発などで補う水の量（培養液1m³あたり何m³か）と水の単価から培養液1m³あたりの額を出し、9円と比べる。菌体の濃さ5g/L（杉浦先生の回答）なら、菌体1kgに培養液200Lを使うので、菌体1kgあたり1.8円は培養液1m³あたり9円にあたる。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり2円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり1.8円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"leaf_label": "補給水（上水）", "quantity": 0.014, "quantity_unit": "m³/kg-DCW", "unit_price": 404, "unit_price_unit": "円/m³", "confidence": "B", "source_kind": "推定", "owner": "杉浦先生（培養液の使い回し）", "note": "量: 蒸発で失う水 10L（2026-09-07 の工程とマテバラ推定の設計仮定）＋ 固形分20%に濃縮した菌体に付いて出ていく水 4L ＝ 0.014m³。菌体を分けたあとの培養液は使い回す前提（捨てるなら菌体1kgに培養液200Lの水が要る）。買値: 上水道 404円/m³（東京都23区、月1,001m³を超える分、税抜）。工業用水が引ければ30円/m³前後（東京都の第一種 29円/m³、2023年3月で廃止）。確かめ方: 培養液を使い回すか、蒸発する量（屋外か屋内か）を杉浦先生に聞き、培養設備を置く場所の水道・工業用水の料金と比べる。使い回す培養液から出す分の下水道の料金（東京都 345円/m³）は入れていない。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_125', 'cm_p21_fuel_260914', 'UPDATE', array['quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'owner', 'note']::text[], '{"quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 2.7, "unit_price_unit": "円/kg-DCW", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 洗浄1回に使う水の量 × 1年の回数 × 水の単価 を、1系列が1年に作る菌体の量で割り、2.7円と比べる。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり3円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり2.7円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"quantity": 0.01, "quantity_unit": "m³/kg-DCW", "unit_price": 404, "unit_price_unit": "円/m³", "owner": "中島先生（洗浄のしかた）", "note": "量: 仮置き。収穫した培養液（菌体1kgで200L）の5%の水で培養槽を洗う → 0.01m³。買値: 上水道 404円/m³（東京都23区、月1,001m³を超える分、税抜）。確かめ方: 洗う回数と1回の水の量（培養槽の容量の何倍か）を中島先生に聞き、1年の水の量 ÷ 1系列が1年に作る菌体の量で比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
