insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_127', 'cm_p21_fuel_260914', 'UPDATE', array['quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'owner', 'note']::text[], '{"quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 9, "unit_price_unit": "円/kg-DCW", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: フィルタ1本の値段 × 1年に替える本数 を、1系列が1年に作る菌体の量で割り、9円と比べる。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり10円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり9円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"quantity": 0.2, "quantity_unit": "m³/kg-DCW", "unit_price": 45, "unit_price_unit": "円/m³", "owner": "中島先生（濃縮のしかた）", "note": "仮置き（膜やフィルタの買値を調べられていない）。2026-08-20版の試算シートでAMDが置いた額（処理水1m³あたり10円）を、培養液1m³あたり45円に直して、菌体1kgの培養液0.2m³（菌体の濃さ5g/L、杉浦先生の回答）を掛けている。確かめ方: 濃縮を遠心分離にするか膜にするかを中島先生と決め、膜なら膜の面積・交換の年数・1m²の値段を見積もって、1年の額 ÷ 1系列が1年に作る菌体の量で比べる（遠心分離ならフィルタはほぼ要らず、電力が要る）。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_128', 'cm_p21_fuel_260914', 'UPDATE', array['leaf_label', 'quantity', 'quantity_unit', 'unit_price', 'unit_price_unit', 'owner', 'note']::text[], '{"leaf_label": "濃縮補助材", "quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 5.4, "unit_price_unit": "円/kg-DCW", "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 菌体を集めやすくする凝集剤などを使うなら、菌体1kgあたりの使用量 × 単価 を出して5.4円と比べる（使わない濃縮のしかたなら0円）。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり6円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり5.4円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"leaf_label": "濃縮補助材（凝集剤）", "quantity": 0.002, "quantity_unit": "kg/kg-DCW", "unit_price": 2700, "unit_price_unit": "円/kg", "owner": "中島先生（濃縮のしかた）", "note": "量: 凝集剤を培養液1Lに10mg（クロレラをキトサン10mg/Lで98%集めた報告。ポリアクリルアミドは5〜10mg/L）× 培養液200L ＝ 0.002kg。買値: 仮置き 2,700円/kg（買値を調べられていない。2026-08-20版の試算シートの額から逆算した値）。確かめ方: 凝集剤を使うか（遠心分離だけなら要らない）と種類を中島先生に聞き、水処理薬剤のメーカーに値段を聞いて比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_134', 'cm_p21_fuel_260914', 'UPDATE', array['quantity', 'quantity_unit', 'unit_price', 'owner', 'note']::text[], '{"quantity": 1, "quantity_unit": "kg-DCW", "unit_price": 5.4, "owner": "AMD", "note": "仮置きの額で、使う量と買値の内訳はない。確かめ方: 培養がうまくいかずに作り直す割合を決め、作り直す割合 × 菌体1kgの原価 を出して5.4円と比べる（1割を作り直すなら、菌体1kgの原価の1割）。出どころ: 2026-08-20版の試算シート（ちこさん作成）でAMDが置いた「処理水1m³あたり6円」を、処理水1m³に使う乾燥菌体1.111kgで割って、菌体1kgあたり5.4円に直した。排水処理のコスト試算からコピーした行で、あちらを直してもこちらは変わらない。"}'::jsonb, '{"quantity": 0.05, "quantity_unit": "kg-DCW/kg-DCW", "unit_price": 261.6, "owner": "杉浦先生（培養の失敗の割合）", "note": "仮置き。培養がうまくいかずに作り直す割合を5%とし、上の原料9行の菌体1kgあたりの合計（261.6円）を掛ける。上の行を書き換えても、この行の単価は自動では変わらない。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 426: 培養の原料を「使う量 × 買値」に組み直した（まさ 2026-09-14「Aで」）。前の値は適用前の DB の写しから記録した', 'migration 426', '2026-09-14T11:08:04.972349+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'ci_260820_123', 'cm_p21_260820', 'UPDATE', array['price_rule', 'note']::text[], '{"price_rule": null, "note": "量: 菌体の乾燥重量の半分が炭素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis 51.4%）→ 菌体1kgに固定するCO2 1.83kg。供給したCO2のうち菌体に固定する割合を80%（同じ設計仮定）として2.29kg。固定する割合は培養のしかたで大きく変わり、閉鎖型の袋の培養で10%と置く試算（米国PNNL 2018）では8倍、開放池で75%（米国エネルギー省 2023）。買値: 50円/kg の仮置き。液化炭酸ガスの卸の相場 FOB東京 約225ドル/t（2026年4〜6月、ChemAnalyst）は1ドル150円で約34円/kgで、届け先までの運賃と貯槽の費用を足した。施設園芸のボンベ買いでは約120円/kg。メーカー各社は2023〜2025年に15〜30%ずつ値上げしている。確かめ方: CO2をどう入れるか（ボンベ・液化炭酸ガスの貯槽・工場の排ガス）と、吸わせきれる割合を杉浦先生に聞き、液化炭酸ガスはメーカー（日本液炭・エア・ウォーター炭酸など）に量と場所で見積を取る。工場の排ガスから回収するなら、国の2030年目標で回収だけ 2,000円台/t（1kgあたり約2〜3円）。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, '{"price_rule": "co2_supply", "note": "量: 菌体の乾燥重量の半分が炭素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis 51.4%）→ 菌体1kgに固定するCO2 1.83kg。供給したCO2のうち菌体に固定する割合を80%（同じ設計仮定）として2.29kg。固定する割合は培養のしかたで大きく変わり、閉鎖型の袋の培養で10%と置く試算（米国PNNL 2018）では8倍、開放池で75%（米国エネルギー省 2023）。買値: 50円/kg の仮置き。液化炭酸ガスの卸の相場 FOB東京 約225ドル/t（2026年4〜6月、ChemAnalyst）は1ドル150円で約34円/kgで、届け先までの運賃と貯槽の費用を足した。施設園芸のボンベ買いでは約120円/kg。メーカー各社は2023〜2025年に15〜30%ずつ値上げしている。確かめ方: CO2をどう入れるか（ボンベ・液化炭酸ガスの貯槽・工場の排ガス）と、吸わせきれる割合を杉浦先生に聞き、液化炭酸ガスはメーカー（日本液炭・エア・ウォーター炭酸など）に量と場所で見積を取る。工場の排ガスから回収するなら、国の2030年目標で回収だけ 2,000円台/t（1kgあたり約2〜3円）。工場の排ガスを使えるなら、この行の「排ガス利用可能」を ON にすると、単価を0円として計算する（買値の欄はそのまま残る。2026-09-14 まさ「それがONのときはCO2コストがゼロになるようにして」）。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 430: CO2 の行に排ガス利用可能のスイッチを置き、培養ロス補充の単価を原料の合計から出すようにした。前の値は適用前の DB の写しから記録した', 'migration 430', '2026-09-14T13:07:38.26427+00:00'::timestamptz);
insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'ci_260820_134', 'cm_p21_260820', 'UPDATE', array['price_rule', 'note']::text[], '{"price_rule": null, "note": "仮置き。培養がうまくいかずに作り直す割合を5%とし、上の原料9行の菌体1kgあたりの合計（261.6円）を掛ける。上の行を書き換えても、この行の単価は自動では変わらない。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, '{"price_rule": "culture_loss", "note": "仮置き。培養がうまくいかずに作り直す割合を5%とし（数量）、上の原料9行の菌体1kgあたりの額の合計を単価として掛ける。単価は上の9行から計算するので、原料の行を書き換えたり、CO2 の「排ガス利用可能」を ON にしたりすると一緒に動く（2026-09-14 から。それまでは合計261.6円を直に置いていて、上の行を書き換えても変わらなかった）。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 430: CO2 の行に排ガス利用可能のスイッチを置き、培養ロス補充の単価を原料の合計から出すようにした。前の値は適用前の DB の写しから記録した', 'migration 430', '2026-09-14T13:07:38.26427+00:00'::timestamptz);
