insert into project_cost_change_log (table_name, row_id, cost_model_id, op, changed_columns, old_values, new_values, reason, changed_by, changed_at) values ('project_cost_items', 'cif_culture_134', 'cm_p21_fuel_260914', 'UPDATE', array['price_rule', 'note']::text[], '{"price_rule": null, "note": "仮置き。培養がうまくいかずに作り直す割合を5%とし、上の原料9行の菌体1kgあたりの合計（261.6円）を掛ける。上の行を書き換えても、この行の単価は自動では変わらない。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, '{"price_rule": "culture_loss", "note": "仮置き。培養がうまくいかずに作り直す割合を5%とし（数量）、上の原料9行の菌体1kgあたりの額の合計を単価として掛ける。単価は上の9行から計算するので、原料の行を書き換えたり、CO2 の「排ガス利用可能」を ON にしたりすると一緒に動く（2026-09-14 から。それまでは合計261.6円を直に置いていて、上の行を書き換えても変わらなかった）。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。"}'::jsonb, 'migration 430: CO2 の行に排ガス利用可能のスイッチを置き、培養ロス補充の単価を原料の合計から出すようにした。前の値は適用前の DB の写しから記録した', 'migration 430', '2026-09-14T13:07:38.26427+00:00'::timestamptz);

-- 出どころを書く（この書き換えはトリガーが記録する）
select set_config('amd.cost_change_reason', 'migration 431: 数字の出どころを説明に書き足した（2026-09-14 まさ「「前の額が何を前提にしていたかは、記録が無くて分からない。」→これはまずいと思う。えいみが作ったんだから、えいみしか分からんよ。こういうことが起きないようにして」）', true);
update project_cost_items set note = '量: 菌体の乾燥重量の8%が窒素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis の測定では11.3%）→ 窒素0.08kg ÷ 硝酸ナトリウムの窒素の割合16.5% ＝ 0.4854kg。培地に入れた窒素はすべて菌体が吸う（培養液を使い回す前提。マテバラ推定と同じ。閉鎖型の培養で吸う割合を20%と置く試算もあり（米国PNNL 2018）、その場合は5倍）。買値: 硝酸ナトリウムの財務省貿易統計の輸入単価（chematels.com の集計、2026年） 187円/kg。届け先までの運賃は含まない。確かめ方: 杉浦先生の培地の窒素源と濃さ（培養液1Lに何g）を聞き、菌体1kgあたりの量と比べる。尿素（窒素46.6%、輸入単価の2026年平均 約107円/kg）が使えるなら菌体1kgあたり約18円に下がる。リン源のりん酸二アンモニウムからも窒素が約9g入るが、ここから差し引いていない。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり9円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「培地主原料　処理水1m³あたり10円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版のメモは「排液利用で大幅低減｜培養液量連動」で、前提の欄に「培地原料低減率 80%（排液利用で大幅低減）」があった（培養を顧客工場で行い、工場の排液を培地に使う形）。7/16版では「培養原料・添加成分　処理水1m³あたり70円」（目標総原価300円から配分した仮置き）の中にあった。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_120';
update project_cost_items set note = '量: 菌体の乾燥重量の1%がリン（2026-09-07 の工程とマテバラ推定の設計仮定。微細藻類で0.3〜1.2%）→ リン0.01kg ÷ りん酸二アンモニウムのリンの割合23.5% ＝ 0.0426kg。入れたリンはすべて菌体が吸う（使い回す前提）。買値: りん酸二アンモニウムの財務省貿易統計の輸入単価（chematels.com の集計、2026年） 161円/kg。確かめ方: 杉浦先生の培地のリン源と濃さを聞いて比べる。BG-11（シアノバクテリアの標準の培地）のリン酸カリウムのままでは、菌体の濃さ5g/Lに足りない（約0.7g/L分）。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり10.8円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「栄養塩　処理水1m³あたり12円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/16版では「培養原料・添加成分　処理水1m³あたり70円」（目標総原価300円から配分した仮置き）の中にあった。7/30版で分けた額の決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_121';
update project_cost_items set note = '量: 菌体の乾燥重量のカリウム1.6%・マグネシウム0.3%・鉄0.1%（スピルリナの成分の総説）から、塩化カリウム0.0305kg・硫酸マグネシウム7水塩0.0304kg・キレート鉄13% 0.0077kg、微量金属の塩（ホウ酸・塩化マンガン・硫酸亜鉛など）をBG-11の鉄との割合で0.0054kg、合わせて0.074kg。買値は重さで割り戻した平均 324円/kg: 塩化カリウム 77円/kg（財務省貿易統計の輸入単価（chematels.com の集計、2026年））、硫酸マグネシウム 162円/kg（肥料・工業用25kg、通販 2026-09）、キレート鉄 1,468円/kg（25kg、通販 2026-09）、微量金属の塩 1,000円/kg（買値を調べていない仮置き）。菌体1kgあたりの額の半分近くがキレート鉄。確かめ方: 杉浦先生の培地の組成を聞き、成分ごとの量と比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり7.2円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「微量元素・添加剤　処理水1m³あたり8円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/16版では「培養原料・添加成分　処理水1m³あたり70円」（目標総原価300円から配分した仮置き）の中にあった。7/30版で分けた額の決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_122';
update project_cost_items set note = '量: 菌体の乾燥重量の半分が炭素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis 51.4%）→ 菌体1kgに固定するCO2 1.83kg。供給したCO2のうち菌体に固定する割合を80%（同じ設計仮定）として2.29kg。固定する割合は培養のしかたで大きく変わり、閉鎖型の袋の培養で10%と置く試算（米国PNNL 2018）では8倍、開放池で75%（米国エネルギー省 2023）。買値: 50円/kg の仮置き。液化炭酸ガスの卸の相場 FOB東京 約225ドル/t（2026年4〜6月、ChemAnalyst）は1ドル150円で約34円/kgで、届け先までの運賃と貯槽の費用を足した。施設園芸のボンベ買いでは約120円/kg。メーカー各社は2023〜2025年に15〜30%ずつ値上げしている。確かめ方: CO2をどう入れるか（ボンベ・液化炭酸ガスの貯槽・工場の排ガス）と、吸わせきれる割合を杉浦先生に聞き、液化炭酸ガスはメーカー（日本液炭・エア・ウォーター炭酸など）に量と場所で見積を取る。工場の排ガスから回収するなら、国の2030年目標で回収だけ 2,000円台/t（1kgあたり約2〜3円）。工場の排ガスを使えるなら、この行の「排ガス利用可能」を ON にすると、単価を0円として計算する（買値の欄はそのまま残る。2026-09-14 まさ「それがONのときはCO2コストがゼロになるようにして」）。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり4.5円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「CO₂　処理水1m³あたり5円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/16版では「CO2/ガス・補助剤　処理水1m³あたり10円」で、根拠は「排ガス利用等も想定した最小構成。詳細仕様未確定。」（排ガスを使う前提の額）。7/30版で5円にした理由はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_123';
update project_cost_items set note = '量: 蒸発で失う水 10L（2026-09-07 の工程とマテバラ推定の設計仮定）＋ 固形分20%に濃縮した菌体に付いて出ていく水 4L ＝ 0.014m³。菌体を分けたあとの培養液は使い回す前提（捨てるなら菌体1kgに培養液200Lの水が要る）。買値: 上水道 404円/m³（東京都23区、月1,001m³を超える分、税抜）。工業用水が引ければ30円/m³前後（東京都の第一種 29円/m³、2023年3月で廃止）。確かめ方: 培養液を使い回すか、蒸発する量（屋外か屋内か）を杉浦先生に聞き、培養設備を置く場所の水道・工業用水の料金と比べる。使い回す培養液から出す分の下水道の料金（東京都 345円/m³）は入れていない。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり1.8円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「補給水　処理水1m³あたり2円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_124';
update project_cost_items set note = '量: 仮置き。収穫した培養液（菌体1kgで200L）の5%の水で培養槽を洗う → 0.01m³。買値: 上水道 404円/m³（東京都23区、月1,001m³を超える分、税抜）。確かめ方: 洗う回数と1回の水の量（培養槽の容量の何倍か）を中島先生に聞き、1年の水の量 ÷ 1系列が1年に作る菌体の量で比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり2.7円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「洗浄水　処理水1m³あたり3円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_125';
update project_cost_items set note = '量: 仮置き。洗浄水1m³に次亜塩素酸ナトリウム12%液を1kg（有効成分 約120mg/L）→ 洗浄水0.01m³で0.01kg。買値: 次亜塩素酸ナトリウム12% 20kgで2,500〜2,905円（通販、2026-09）の中ほど135円/kg。確かめ方: 洗浄に使う薬剤と濃さ、洗う回数を中島先生に聞いて比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり4.5円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「洗浄薬剤　処理水1m³あたり5円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_126';
update project_cost_items set note = '仮置き（膜やフィルタの買値を調べられていない）。2026-08-20版の試算シートでAMDが置いた額（処理水1m³あたり10円）を、培養液1m³あたり45円に直して、菌体1kgの培養液0.2m³（菌体の濃さ5g/L、杉浦先生の回答）を掛けている。確かめ方: 濃縮を遠心分離にするか膜にするかを中島先生と決め、膜なら膜の面積・交換の年数・1m²の値段を見積もって、1年の額 ÷ 1系列が1年に作る菌体の量で比べる（遠心分離ならフィルタはほぼ要らず、電力が要る）。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり9円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「濃縮用フィルタ　処理水1m³あたり10円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_127';
update project_cost_items set note = '量: 凝集剤を培養液1Lに10mg（クロレラをキトサン10mg/Lで98%集めた報告。ポリアクリルアミドは5〜10mg/L）× 培養液200L ＝ 0.002kg。買値: 仮置き 2,700円/kg（買値を調べられていない。2026-08-20版の試算シートの額から逆算した値）。確かめ方: 凝集剤を使うか（遠心分離だけなら要らない）と種類を中島先生に聞き、水処理薬剤のメーカーに値段を聞いて比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり5.4円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「濃縮補助材　処理水1m³あたり6円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_128';
update project_cost_items set note = '仮置き。培養がうまくいかずに作り直す割合を5%とし（数量）、上の原料9行の菌体1kgあたりの額の合計を単価として掛ける。単価は上の9行から計算するので、原料の行を書き換えたり、CO2 の「排ガス利用可能」を ON にしたりすると一緒に動く（2026-09-14 から。それまでは合計261.6円を直に置いていて、上の行を書き換えても変わらなかった）。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。コスト試算（燃料）の培養設備の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり5.4円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「培養ロス補充　処理水1m³あたり6円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版のメモは「菌体量連動」。決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'ci_260820_134';
update project_cost_items set note = '量: 菌体の乾燥重量の8%が窒素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis の測定では11.3%）→ 窒素0.08kg ÷ 硝酸ナトリウムの窒素の割合16.5% ＝ 0.4854kg。培地に入れた窒素はすべて菌体が吸う（培養液を使い回す前提。マテバラ推定と同じ。閉鎖型の培養で吸う割合を20%と置く試算もあり（米国PNNL 2018）、その場合は5倍）。買値: 硝酸ナトリウムの財務省貿易統計の輸入単価（chematels.com の集計、2026年） 187円/kg。届け先までの運賃は含まない。確かめ方: 杉浦先生の培地の窒素源と濃さ（培養液1Lに何g）を聞き、菌体1kgあたりの量と比べる。尿素（窒素46.6%、輸入単価の2026年平均 約107円/kg）が使えるなら菌体1kgあたり約18円に下がる。リン源のりん酸二アンモニウムからも窒素が約9g入るが、ここから差し引いていない。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり9円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「培地主原料　処理水1m³あたり10円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版のメモは「排液利用で大幅低減｜培養液量連動」で、前提の欄に「培地原料低減率 80%（排液利用で大幅低減）」があった（培養を顧客工場で行い、工場の排液を培地に使う形）。7/16版では「培養原料・添加成分　処理水1m³あたり70円」（目標総原価300円から配分した仮置き）の中にあった。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_120';
update project_cost_items set note = '量: 菌体の乾燥重量の1%がリン（2026-09-07 の工程とマテバラ推定の設計仮定。微細藻類で0.3〜1.2%）→ リン0.01kg ÷ りん酸二アンモニウムのリンの割合23.5% ＝ 0.0426kg。入れたリンはすべて菌体が吸う（使い回す前提）。買値: りん酸二アンモニウムの財務省貿易統計の輸入単価（chematels.com の集計、2026年） 161円/kg。確かめ方: 杉浦先生の培地のリン源と濃さを聞いて比べる。BG-11（シアノバクテリアの標準の培地）のリン酸カリウムのままでは、菌体の濃さ5g/Lに足りない（約0.7g/L分）。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり10.8円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「栄養塩　処理水1m³あたり12円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/16版では「培養原料・添加成分　処理水1m³あたり70円」（目標総原価300円から配分した仮置き）の中にあった。7/30版で分けた額の決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_121';
update project_cost_items set note = '量: 菌体の乾燥重量のカリウム1.6%・マグネシウム0.3%・鉄0.1%（スピルリナの成分の総説）から、塩化カリウム0.0305kg・硫酸マグネシウム7水塩0.0304kg・キレート鉄13% 0.0077kg、微量金属の塩（ホウ酸・塩化マンガン・硫酸亜鉛など）をBG-11の鉄との割合で0.0054kg、合わせて0.074kg。買値は重さで割り戻した平均 324円/kg: 塩化カリウム 77円/kg（財務省貿易統計の輸入単価（chematels.com の集計、2026年））、硫酸マグネシウム 162円/kg（肥料・工業用25kg、通販 2026-09）、キレート鉄 1,468円/kg（25kg、通販 2026-09）、微量金属の塩 1,000円/kg（買値を調べていない仮置き）。菌体1kgあたりの額の半分近くがキレート鉄。確かめ方: 杉浦先生の培地の組成を聞き、成分ごとの量と比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり7.2円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「微量元素・添加剤　処理水1m³あたり8円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/16版では「培養原料・添加成分　処理水1m³あたり70円」（目標総原価300円から配分した仮置き）の中にあった。7/30版で分けた額の決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_122';
update project_cost_items set note = '量: 菌体の乾燥重量の半分が炭素（2026-09-07 の工程とマテバラ推定の設計仮定。Synechocystis 51.4%）→ 菌体1kgに固定するCO2 1.83kg。供給したCO2のうち菌体に固定する割合を80%（同じ設計仮定）として2.29kg。固定する割合は培養のしかたで大きく変わり、閉鎖型の袋の培養で10%と置く試算（米国PNNL 2018）では8倍、開放池で75%（米国エネルギー省 2023）。買値: 50円/kg の仮置き。液化炭酸ガスの卸の相場 FOB東京 約225ドル/t（2026年4〜6月、ChemAnalyst）は1ドル150円で約34円/kgで、届け先までの運賃と貯槽の費用を足した。施設園芸のボンベ買いでは約120円/kg。メーカー各社は2023〜2025年に15〜30%ずつ値上げしている。確かめ方: CO2をどう入れるか（ボンベ・液化炭酸ガスの貯槽・工場の排ガス）と、吸わせきれる割合を杉浦先生に聞き、液化炭酸ガスはメーカー（日本液炭・エア・ウォーター炭酸など）に量と場所で見積を取る。工場の排ガスから回収するなら、国の2030年目標で回収だけ 2,000円台/t（1kgあたり約2〜3円）。工場の排ガスを使えるなら、この行の「排ガス利用可能」を ON にすると、単価を0円として計算する（買値の欄はそのまま残る。2026-09-14 まさ「それがONのときはCO2コストがゼロになるようにして」）。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり4.5円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「CO₂　処理水1m³あたり5円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/16版では「CO2/ガス・補助剤　処理水1m³あたり10円」で、根拠は「排ガス利用等も想定した最小構成。詳細仕様未確定。」（排ガスを使う前提の額）。7/30版で5円にした理由はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_123';
update project_cost_items set note = '量: 蒸発で失う水 10L（2026-09-07 の工程とマテバラ推定の設計仮定）＋ 固形分20%に濃縮した菌体に付いて出ていく水 4L ＝ 0.014m³。菌体を分けたあとの培養液は使い回す前提（捨てるなら菌体1kgに培養液200Lの水が要る）。買値: 上水道 404円/m³（東京都23区、月1,001m³を超える分、税抜）。工業用水が引ければ30円/m³前後（東京都の第一種 29円/m³、2023年3月で廃止）。確かめ方: 培養液を使い回すか、蒸発する量（屋外か屋内か）を杉浦先生に聞き、培養設備を置く場所の水道・工業用水の料金と比べる。使い回す培養液から出す分の下水道の料金（東京都 345円/m³）は入れていない。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり1.8円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「補給水　処理水1m³あたり2円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_124';
update project_cost_items set note = '量: 仮置き。収穫した培養液（菌体1kgで200L）の5%の水で培養槽を洗う → 0.01m³。買値: 上水道 404円/m³（東京都23区、月1,001m³を超える分、税抜）。確かめ方: 洗う回数と1回の水の量（培養槽の容量の何倍か）を中島先生に聞き、1年の水の量 ÷ 1系列が1年に作る菌体の量で比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり2.7円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「洗浄水　処理水1m³あたり3円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_125';
update project_cost_items set note = '量: 仮置き。洗浄水1m³に次亜塩素酸ナトリウム12%液を1kg（有効成分 約120mg/L）→ 洗浄水0.01m³で0.01kg。買値: 次亜塩素酸ナトリウム12% 20kgで2,500〜2,905円（通販、2026-09）の中ほど135円/kg。確かめ方: 洗浄に使う薬剤と濃さ、洗う回数を中島先生に聞いて比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり4.5円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「洗浄薬剤　処理水1m³あたり5円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_126';
update project_cost_items set note = '仮置き（膜やフィルタの買値を調べられていない）。2026-08-20版の試算シートでAMDが置いた額（処理水1m³あたり10円）を、培養液1m³あたり45円に直して、菌体1kgの培養液0.2m³（菌体の濃さ5g/L、杉浦先生の回答）を掛けている。確かめ方: 濃縮を遠心分離にするか膜にするかを中島先生と決め、膜なら膜の面積・交換の年数・1m²の値段を見積もって、1年の額 ÷ 1系列が1年に作る菌体の量で比べる（遠心分離ならフィルタはほぼ要らず、電力が要る）。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり9円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「濃縮用フィルタ　処理水1m³あたり10円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_127';
update project_cost_items set note = '量: 凝集剤を培養液1Lに10mg（クロレラをキトサン10mg/Lで98%集めた報告。ポリアクリルアミドは5〜10mg/L）× 培養液200L ＝ 0.002kg。買値: 仮置き 2,700円/kg（買値を調べられていない。2026-08-20版の試算シートの額から逆算した値）。確かめ方: 凝集剤を使うか（遠心分離だけなら要らない）と種類を中島先生に聞き、水処理薬剤のメーカーに値段を聞いて比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり5.4円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「濃縮補助材　処理水1m³あたり6円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版で置かれた額で、決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_128';
update project_cost_items set note = '仮置き。培養がうまくいかずに作り直す割合を5%とし（数量）、上の原料9行の菌体1kgあたりの額の合計を単価として掛ける。単価は上の9行から計算するので、原料の行を書き換えたり、CO2 の「排ガス利用可能」を ON にしたりすると一緒に動く（2026-09-14 から。それまでは合計261.6円を直に置いていて、上の行を書き換えても変わらなかった）。確かめ方: 1年に失敗する培養の割合を杉浦先生に聞いて比べる。排水処理のコスト試算の同じ行と同じ値（2026-09-14 にそろえた）。片方を直しても、もう片方は変わらない。前の額（2026-09-14 に「使う量 × 買値」へ組み直す前）: 菌体1kgあたり5.4円で、量と買値の内訳は無かった。ちこさんの試算シート（2026-07-30版〜2026-08-20版）の「培養ロス補充　処理水1m³あたり6円」（出所「仮置き」）を、処理水1m³に使う乾燥菌体1.111kgで割った額。7/30版のメモは「菌体量連動」。決め方はシートに書かれていない。版ごとの流れは版の履歴「培養の原料の前の額は、どこから来たか」。', updated_at = now() where cost_item_id = 'cif_culture_134';
